function previewTrialInfo(){try{const raw=localStorage.getItem(PREVIEW_TRIAL_KEY),started=raw?Number(raw):Date.now(),expires=started+DAYS*86400000;if(!raw)localStorage.setItem(PREVIEW_TRIAL_KEY,String(started));return{startedAt:started,expiresAt:expires,active:Date.now()<expires,daysRemaining:Math.max(0,Math.ceil((expires-Date.now())/86400000))}}catch(e){const started=Date.now();return{startedAt:started,expiresAt:started+DAYS*86400000,active:true,daysRemaining:DAYS}}}
function selectedRole(){return localStorage.getItem(ROLE_KEY)||"RT_OPERATOR"}
