function roleOptions(selected,trialOnly=false){return Object.entries(ROLE_DEFS).filter(([code])=>code!=="PILOT_VIEWER"&&(!trialOnly||TRIAL_ROLES.includes(code))).map(([code,d])=>'<option value="'+code+'" '+(selected===code?"selected":"")+'>'+esc(d.label)+'</option>').join("")}
function landingRoleCards(){return TRIAL_ROLES.map(code=>{const d=ROLE_DEFS[code],active=selectedRole()===code;return '<button type="button" class="role-card '+(active?"active":"")+'" data-landing-role="'+code+'"><b>'+esc(d.label)+'</b><span>'+esc(d.desc)+'</span></button>'}).join("")}
