function verified(user){return !!(user?.email_confirmed_at||user?.confirmed_at)}
async function getCurrentUser(){if(!sb)return null;const r=await sb.auth.getUser();return r.data?.user||null}
async function resolveAccess(user){if(!user)return{code:"PILOT_VIEWER",source:"signed_out"};try{const q=await sb.from("role_assignments").select("role_id,scope_territory_id,active,ends_at,roles(role_code)").eq("user_id",user.id).eq("active",true);if(!q.error&&q.data?.length){const assigned=q.data.map(x=>x.roles?.role_code).filter(Boolean),selected=selectedRole(),code=assigned.includes(selected)?selected:assigned[0];return{code,source:"assignment",assigned}}}catch(e){console.warn("role resolution",e)}const trial=trialInfo(user),requested=requestedRole(user);if(verified(user)&&trial?.active&&TRIAL_ROLES.includes(requested))return{code:requested,source:"verified_trial_ui",requestedRole:requested,trial};return{code:"PILOT_VIEWER",source:"pending_approval",requestedRole:requested,trial}}
