function go(v,s,push=true){if(push&&(state.view!==v||state.sub!==s))state.history.push([state.view,state.sub]);state.forward=[];state.view=v;state.sub=s;state.selected.clear();render()}
function back(){const h=state.history.pop();if(!h){toast("Tidak ada halaman sebelumnya");return}state.forward.push([state.view,state.sub]);state.view=h[0];state.sub=h[1];render()}
function next(){const h=state.forward.pop();if(!h){const idx=modules[state.view][2].findIndex(x=>x[0]===state.sub),a=modules[state.view][2][idx+1];if(a){state.history.push([state.view,state.sub]);state.sub=a[0];render()}else toast("Sudah di submenu terakhir");return}state.history.push([state.view,state.sub]);state.view=h[0];state.sub=h[1];render()}
