async function refreshLiveWorkspace(){
  if(!sb)return;
  const host=document.querySelector(".workspace-table"); if(!host)return;
  const scope=liveDemoScope(), module=state.view.toUpperCase(), sub=state.sub;
  try{
    let rows=await canonicalDemoRows(state.view,sub,scope);
    if(rows===null)rows=[];
    if(rows.length){
      updateLiveKpis([["DATA DOMAIN",rows.length,"Record demo terhubung ke tabel domain"],["SUMBER","CANONICAL","Data sintetis / baca-saja"],["AKSI","DETAIL","Perubahan resmi memerlukan alur CRUD terpisah"]]);
    }else if(state.view==="warga"){
      const [portal,people,households]=await Promise.all([
        liveCount("demo_portal_items",{territory_id:scope}),
        liveCount("persons",{status:"ACTIVE"}),
        liveCount("households",{status:"ACTIVE"})
      ]);
      updateLiveKpis([["PORTAL ITEMS",portal,"Data portal"],["WARGA",people,"Canonical person records"],["KK",households,"Canonical household records"]]);
      rows=await demoRows("WARGA_PORTAL",sub);
    }else if(state.view==="rt"){
      const [demo,people,households]=await Promise.all([
        liveCount("demo_operational_records",{territory_id:scope,module_code:"RT_DIGITAL",submenu_code:sub}),
        liveCount("persons"),liveCount("households")
      ]);
      updateLiveKpis([["SUBMENU",demo,"Record tersimpan"],["WARGA",people,"Canonical data"],["KK",households,"Canonical data"]]);
      rows=await demoRows("RT_DIGITAL",sub);
    }else if(state.view==="rw"){
      rows=await demoRows("RW_DIGITAL",sub);
      updateLiveKpis([["RW RECORDS",rows.length,"Record operasional"],["STATUS",rows.filter(x=>x.status==="APPROVED").length,"Approved"],["PENDING",rows.filter(x=>x.status==="SUBMITTED").length,"Needs review"]]);
    }else if(state.view==="desa"){
      rows=await demoRows("DESA_DIGITAL",sub);
      updateLiveKpis([["DESA RECORDS",rows.length,"Record operasional"],["VALIDATED",rows.filter(x=>x.status==="VILLAGE_VALIDATED").length,"Validated"],["SUBMITTED",rows.filter(x=>x.status==="SUBMITTED").length,"Needs action"]]);
    }else if(state.view==="smart"){
      rows=await demoRows("SMART_VILLAGE",sub);
      updateLiveKpis([["INDICATORS",rows.length,"Record indikator"],["ACTIVE",rows.filter(x=>x.status==="ACTIVE").length,"Active"],["MONITORING",rows.filter(x=>x.status==="MONITORING").length,"Monitoring"]]);
    }else if(state.view==="dokumen"){
      rows=await demoRows("DOC_TTE",sub);
      updateLiveKpis([["DOCUMENTS",rows.length,"Alur dokumen"],["SIGNED",rows.filter(x=>x.status==="SIGNED").length,"Signed"],["PENDING",rows.filter(x=>x.status==="TTE_REQUESTED").length,"Awaiting TTE"]]);
    }else if(state.view==="kegiatan"){
      const ev=await liveCount("community_events",{territory_id:scope});
      updateLiveKpis([["KEGIATAN",ev,"Community events"],["ARISAN",await liveCount("arisan_groups",{territory_id:scope}),"Kelompok aktif"],["KAS",await liveCount("rt_rw_cash_transactions",{reference:"DEMO-SEED"}),"Transaksi kas"]]);
    }else if(state.view==="layanan"){
      rows=await demoRows("LAYANAN",sub);
      updateLiveKpis([["LAYANAN",rows.length,"Record layanan"],["SUBMITTED",rows.filter(x=>x.status==="SUBMITTED").length,"Submitted"],["RESOLVED",rows.filter(x=>x.status==="RESOLVED").length,"Resolved"]]);
    }else{
      // All remaining menu surfaces read their own seeded operational records.
      // This keeps the demo dataset visible across modules without exposing canonical PII in public preview.
      const sourceMap={identitas:["IDENTITY",sub],jolie:["JOLIE_BUSINESS",sub],gis:["GIS",sub],whatsapp:["WHATSAPP",sub],sid:["SID_BRIDGE",sub],gpffe:["GPFFE_EXCHANGE",sub],admin:["PLATFORM_ADMIN",sub],dataquality:["DATA_QUALITY",sub],smart:["SMART_VILLAGE",sub],dokumen:["DOC_TTE",sub],desa:["DESA_DIGITAL",sub],rw:["RW_DIGITAL",sub],kegiatan:["COMMUNITY",sub],warga:["WARGA_PORTAL",sub],rt:["RT_DIGITAL",sub],layanan:["LAYANAN",sub]};
      const source=sourceMap[state.view]||[state.view.toUpperCase(),sub];
      rows=await demoRows(source[0],source[1]);
      if(!rows.length)rows=await demoRows(source[0],null);
      updateLiveKpis([["MENU",titleForLiveModule(state.view),"Workspace aktif"],["DATASET",rows.length,"Record contoh tersimpan"],["STATUS","DEMO","Data simulasi; bukan data resmi"]]);
    }
    if(!rows.length){
      const fallbackMap={dashboard:"PLATFORM_ADMIN",warga:"WARGA_PORTAL",rt:"RT_DIGITAL",rw:"RW_DIGITAL",desa:"DESA_DIGITAL",smart:"SMART_VILLAGE",dokumen:"DOC_TTE",kegiatan:"COMMUNITY",layanan:"LAYANAN",identitas:"IDENTITY",jolie:"JOLIE_BUSINESS",gis:"GIS",whatsapp:"WHATSAPP",sid:"SID_BRIDGE",gpffe:"GPFFE_EXCHANGE",admin:"PLATFORM_ADMIN",dataquality:"DATA_QUALITY"};
      const fallbackModule=fallbackMap[state.view];
      if(fallbackModule)rows=await demoRows(fallbackModule,null);
    }
    renderLiveRows(rows);
  }catch(e){console.warn("live workspace",e)}
}
