 if(!rows.length)rows=[{id:"demo-prov",parent_id:null,territory_type:"PROVINCE",code:"ID-JB",name:"Jawa Barat",active:true},{id:"demo-kab",parent_id:"demo-prov",territory_type:"REGENCY_CITY",code:"KAB-001",name:"Kabupaten",active:true},{id:"demo-kec",parent_id:"demo-kab",territory_type:"DISTRICT",code:"KEC-001",name:"Kecamatan",active:true},{id:"demo-desa",parent_id:"demo-kec",territory_type:"VILLAGE",code:"DESA-001",name:"RT 001 / RW 001",active:true}];
 const byId=new Map(rows.map(x=>[x.id,x]));const level=x=>({PROVINCE:"Provinsi",REGENCY_CITY:"Kab/Kota",DISTRICT:"Kecamatan",VILLAGE:"Desa/Kelurahan",HAMLET:"Dusun",RW:"RW",RT:"RT"}[x]||x);
